corrected_code:
@login_required
def update_leave_request(request, request_id):
    leave_req = get_object_or_404(LeaveRequest, id=request_id, employee=request.user)
    if request.method == 'POST':
        form = LeaveRequestForm(request.POST, instance=leave_req)
        if form.is_valid():
            form.save()
            return redirect('leave_list')
    else:
        form = LeaveRequestForm(instance=leave_req)
    return render(request, 'hr/edit_leave.html', {'form': form, 'leave': leave_req})
